package local.ambilight.reader;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import javax.net.ssl.*;import java.net.*;import java.io.*;import java.security.*;import java.util.*;import java.util.regex.*;
public class ReaderService extends Service {
 public static volatile JSONObject frame; public static volatile String status="Durduruldu"; public static volatile long count=0,errors=0,latency=0,last=0; public static volatile boolean running=false;
 public static volatile HueFleet fleet;
 private Thread worker;private volatile boolean stop=false;private String user,key;
 public void onCreate(){super.onCreate();fleet=new HueFleet(this);for(String name:new String[]{"latest.json","latest.json.bak","latest.json.new","latest.tmp","frames.jsonl","frames.previous.jsonl"}){File old=new File(getFilesDir(),name);if(old.exists())old.delete();}}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"STOP".equals(i.getAction())){getSharedPreferences("settings",0).edit().putBoolean("enabled",false).apply();stopSelf();return START_NOT_STICKY;}getSharedPreferences("settings",0).edit().putBoolean("enabled",true).apply();NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("reader","Freelight",NotificationManager.IMPORTANCE_LOW));PendingIntent pi=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);PendingIntent end=PendingIntent.getService(this,1,new Intent(this,ReaderService.class).setAction("STOP"),PendingIntent.FLAG_IMMUTABLE);startForeground(1,new Notification.Builder(this,"reader").setSmallIcon(android.R.drawable.ic_menu_view).setContentTitle(I18n.text(I18n.wrap(this),"notification_title")).setContentText(I18n.text(I18n.wrap(this),"notification_text")).setContentIntent(pi).addAction(new Notification.Action.Builder(null,I18n.text(I18n.wrap(this),"stop"),end).build()).build());if(worker==null){stop=false;worker=new Thread(this::loop,"AmbilightReader");worker.start();}return START_STICKY;}
 private String md5(String text)throws Exception{byte[] b=MessageDigest.getInstance("MD5").digest(text.getBytes("UTF-8"));StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(Locale.US,"%02x",x&255));return s.toString();}
 public static volatile String endpoint="Yerel adres aranıyor";
 private SSLSocket transport; private InputStream transportIn; private String sessionHost;private int addressAttempt=0;
 private String findLocalAddress()throws Exception{
  List<String> addresses=new ArrayList<>();addresses.add("127.0.0.1");
  Enumeration<NetworkInterface> interfaces=NetworkInterface.getNetworkInterfaces();
  while(interfaces!=null&&interfaces.hasMoreElements()){NetworkInterface network=interfaces.nextElement();if(!network.isUp()||network.isLoopback())continue;Enumeration<InetAddress> values=network.getInetAddresses();while(values.hasMoreElements()){InetAddress address=values.nextElement();if(address instanceof Inet4Address&&address.isSiteLocalAddress())addresses.add(address.getHostAddress());}}
  return addresses.get(addressAttempt%addresses.size());
 }
 protected void dump(FileDescriptor fd,PrintWriter writer,String[] args){try{JSONArray bulbs=new JSONArray();HueBle ble=null;if(fleet!=null)for(HueBle b:fleet.bulbs()){if(ble==null)ble=b;bulbs.put(new JSONObject().put("id",b.id()).put("name",b.savedName()).put("source",b.source).put("status",b.status).put("ready",b.ready).put("syncing",b.syncing).put("automatic",b.automatic).put("paused",b.isPaused()).put("writes",b.writes).put("failures",b.failures).put("light_on",b.isLightOn()).put("brightness_percent",b.brightnessPercent).put("brightness",b.lastBrightness));}JSONObject snapshot=new JSONObject().put("running",running).put("status",status==null?"":status).put("samples",count).put("errors",errors).put("latency_ms",latency).put("endpoint",endpoint).put("last_elapsed_ms",last).put("age_ms",last==0?-1:SystemClock.elapsedRealtime()-last).put("ble_status",ble==null?"":ble.status).put("ble_ready",ble!=null&&ble.ready).put("ble_sync",ble!=null&&ble.syncing).put("ble_writes",ble==null?0:ble.writes).put("ble_failures",ble==null?0:ble.failures).put("ble_model",ble==null?"":ble.model).put("ble_automatic",ble!=null&&ble.automatic).put("ble_screen_on",ble!=null&&ble.screenOn).put("ble_source",ble==null?"":ble.source).put("ble_multiplier",ble==null?0:ble.brightnessPercent/100.0).put("ble_brightness",ble==null?0:ble.lastBrightness).put("ble_recoveries",ble==null?0:ble.recoveries).put("ble_devices",ble==null?0:ble.devices().size()).put("ble_trace",ble==null?"":ble.trace).put("ble_snapshot",ble==null?"":ble.snapshot).put("ble_operation",ble==null?"":ble.operation).put("bulbs",bulbs).put("frame",frame==null?JSONObject.NULL:frame);writer.println(snapshot.toString());}catch(Exception e){writer.println("State unavailable");}}

 private void resetTransport(){try{if(transport!=null)transport.close();}catch(Exception ignored){}transport=null;transportIn=null;}
 private class LocalRequest {
  String path;Map<String,String> requestHeaders=new HashMap<>(),headers=new HashMap<>();int code=-1;byte[] body;
  LocalRequest(String p){path=p;}void setRequestProperty(String k,String v){requestHeaders.put(k,v);}String getHeaderField(String k){return headers.get(k.toLowerCase(Locale.US));}void disconnect(){}InputStream getInputStream()throws Exception{execute();return new ByteArrayInputStream(body);}int getResponseCode()throws Exception{execute();return code;}
  String line(InputStream in)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();int c;while((c=in.read())!=-1){if(c==10)break;if(c!=13)b.write(c);if(b.size()>8192)throw new IOException("HTTP satırı çok uzun");}return b.toString("UTF-8");}
  void execute()throws Exception{if(code!=-1)return;try{if(transport==null){sessionHost=findLocalAddress();endpoint=sessionHost;Socket plain=new Socket();plain.connect(new InetSocketAddress(sessionHost,1926),2000);plain.setSoTimeout(3000);SSLContext fresh=SSLContext.getInstance("TLS");fresh.init(null,new TrustManager[]{new X509TrustManager(){public java.security.cert.X509Certificate[] getAcceptedIssuers(){return new java.security.cert.X509Certificate[0];}public void checkClientTrusted(java.security.cert.X509Certificate[] c,String a){}public void checkServerTrusted(java.security.cert.X509Certificate[] c,String a){}}},new SecureRandom());transport=(SSLSocket)fresh.getSocketFactory().createSocket(plain,sessionHost,1926,true);transport.setSoTimeout(3000);transport.startHandshake();transportIn=transport.getInputStream();}StringBuilder req=new StringBuilder("GET "+path+" HTTP/1.1\r\nHost: "+sessionHost+":1926\r\nConnection: keep-alive\r\n");for(Map.Entry<String,String> h:requestHeaders.entrySet())req.append(h.getKey()+": "+h.getValue()+"\r\n");req.append("\r\n");transport.getOutputStream().write(req.toString().getBytes("UTF-8"));transport.getOutputStream().flush();InputStream in=transportIn;String first=line(in);String[] parts=first.split(" ");if(parts.length<2)throw new IOException("Geçersiz HTTP yanıtı");int receivedCode=Integer.parseInt(parts[1]);String l;while(!(l=line(in)).isEmpty()){int colon=l.indexOf(':');if(colon>0)headers.put(l.substring(0,colon).toLowerCase(Locale.US),l.substring(colon+1).trim());}ByteArrayOutputStream out=new ByteArrayOutputStream();if("chunked".equalsIgnoreCase(headers.get("transfer-encoding"))){while(true){int length=Integer.parseInt(line(in).split(";",2)[0].trim(),16);if(length==0){while(!line(in).isEmpty()){}break;}copy(in,out,length);line(in);}}else if(headers.containsKey("content-length")){copy(in,out,Integer.parseInt(headers.get("content-length")));}else throw new IOException("Yanıt uzunluğu yok");body=out.toByteArray();code=receivedCode;if("close".equalsIgnoreCase(headers.get("connection")))resetTransport();}catch(Exception e){resetTransport();addressAttempt++;throw e;}}
  void copy(InputStream in,ByteArrayOutputStream out,int length)throws Exception{if(length<0||out.size()+length>65536)throw new IOException("Yanıt çok büyük");byte[] buf=new byte[4096];while(length>0){int n=in.read(buf,0,Math.min(buf.length,length));if(n<0)throw new EOFException();out.write(buf,0,n);length-=n;}}
 }
 private LocalRequest connection(String path){return new LocalRequest(path);}
 private JSONObject read()throws Exception{String path="/6/ambilight/measured";LocalRequest c=connection(path);try{if(c.getResponseCode()==401){String challenge=c.getHeaderField("WWW-Authenticate");c.disconnect();Map<String,String> v=new HashMap<>();Matcher m=Pattern.compile("(\\w+)=(?:\"([^\"]*)\"|([^, ]+))").matcher(challenge==null?"":challenge);while(m.find())v.put(m.group(1),m.group(2)!=null?m.group(2):m.group(3));String realm=v.get("realm"),nonce=v.get("nonce"),algorithm=v.get("algorithm");if(realm==null||nonce==null)throw new IOException("Digest yanıtı eksik");if(algorithm!=null&&!algorithm.equalsIgnoreCase("MD5"))throw new IOException("Desteklenmeyen digest algoritması");String a1=md5(user+":"+realm+":"+key),a2=md5("GET:"+path),cn=UUID.randomUUID().toString().replace("-",""),response;String auth="Digest username=\""+user+"\", realm=\""+realm+"\", nonce=\""+nonce+"\", uri=\""+path+"\"";if(v.containsKey("qop")){if(!Arrays.asList(v.get("qop").split(",")).contains("auth"))throw new IOException("Digest auth desteklenmiyor");response=md5(a1+":"+nonce+":00000001:"+cn+":auth:"+a2);auth+=", qop=auth, nc=00000001, cnonce=\""+cn+"\"";}else response=md5(a1+":"+nonce+":"+a2);auth+=", response=\""+response+"\"";if(v.containsKey("opaque"))auth+=", opaque=\""+v.get("opaque")+"\"";c=connection(path);c.setRequestProperty("Authorization",auth);}int code=c.getResponseCode();if(code!=200)throw new IOException("TV HTTP "+code);ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>65536)throw new IOException("Yanıt çok büyük");}}JSONObject data=new JSONObject(out.toString("UTF-8"));JSONObject layer=data.getJSONObject("layer1");for(String side:new String[]{"left","top","right"}){JSONObject zones=layer.getJSONObject(side);if(zones.length()==0)throw new IOException("Eksik bölge");Iterator<String> it=zones.keys();while(it.hasNext()){JSONObject color=zones.getJSONObject(it.next());for(String ch:new String[]{"r","g","b"}){Object value=color.get(ch);if(!(value instanceof Integer)||((Integer)value)<0||((Integer)value)>255)throw new IOException("Geçersiz RGB");}}}return data;}finally{c.disconnect();}}
 private void loop(){running=true;int consecutive=0;while(!stop){long started=SystemClock.elapsedRealtime();try{if(user==null){try(FileInputStream in=new FileInputStream(new File(getFilesDir(),"pairing.json"))){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[1024];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);JSONObject s=new JSONObject(b.toString("UTF-8"));user=s.getJSONObject("device").getString("id");key=s.getJSONObject("response").getString("auth_key");}}JSONObject data=read();frame=data;count++;last=SystemClock.elapsedRealtime();latency=last-started;status="Bağlı";consecutive=0;Thread.sleep(Math.max(1,200-latency));}catch(Exception e){if(stop)break;errors++;consecutive++;status=e.getMessage();try{Thread.sleep(Math.min(15000,500L*(1L<<Math.min(consecutive,5))));}catch(InterruptedException end){break;}}}running=false;}
 public void onDestroy(){if(fleet!=null){fleet.close();fleet=null;}stop=true;resetTransport();if(worker!=null)worker.interrupt();status="Durduruldu";super.onDestroy();}public IBinder onBind(Intent i){return null;}
}
